// Robot families, requirements, and part presets share one saved project state.
const families={
 arm:{name:'Robotic arm',icon:'⌁',tag:'REACH · GRASP · PLACE',description:'A configurable articulated arm for handling objects.',parts:['upper','forearm','jaw','base','bracket','enclosure'],fields:['task','upperLength','foreLength','toolLength','payload','joints','gripOpening','upperMass','foreMass','toolMass','margin']},
 rover:{name:'Wheeled robot',icon:'◉',tag:'DRIVE · EXPLORE · CARRY',description:'A two-motor differential-drive mobile platform.',parts:['plate','wheel','bracket','enclosure','sensor'],fields:['mission','bodyLength','bodyWidth','wheelDiameter','payload','robotMass','speed','slope','terrain']},
 tracked:{name:'Tracked robot',icon:'▰',tag:'TRACTION · TERRAIN · LOAD',description:'A skid-steer platform with two driven tracks.',parts:['plate','roller','bracket','enclosure','sensor'],fields:['mission','bodyLength','bodyWidth','wheelDiameter','trackWidth','payload','robotMass','speed','slope','terrain']},
 walker:{name:'Legged robot',icon:'⋔',tag:'STEP · BALANCE · ADAPT',description:'A quadruped or hexapod with articulated legs.',parts:['plate','leg','foot','bracket','enclosure'],fields:['legs','legJoints','legLength','bodyLength','bodyWidth','payload','robotMass','terrain']},
 gantry:{name:'Cartesian / gantry',icon:'⌗',tag:'POSITION · SORT · REPEAT',description:'A linear XYZ robot for a rectangular workspace.',parts:['carriage','bracket','base','enclosure','sensor'],fields:['travelX','travelY','travelZ','payload','carriageWidth','precision','feedRate']},
 turret:{name:'Pan / tilt robot',icon:'◎',tag:'AIM · OBSERVE · TRACK',description:'A two-axis mount for a camera or sensor.',parts:['base','bracket','sensor','enclosure'],fields:['panRange','tiltRange','payload','toolOffset','mountWidth']}
};
const purposeDefaults={family:'rover',task:'pick',upperLength:180,foreLength:160,toolLength:60,payload:.25,joints:4,gripOpening:60,upperMass:.15,foreMass:.12,toolMass:.10,margin:2,bodyLength:200,bodyWidth:140,wheelDiameter:70,trackWidth:35,robotMass:1,speed:.3,slope:5,terrain:'indoor',legs:4,legJoints:3,legLength:100,travelX:200,travelY:200,travelZ:100,carriageWidth:80,precision:.5,feedRate:30,panRange:180,tiltRange:90,toolOffset:50,mountWidth:70};
const fieldSpecs={
 task:['Primary task', ['pick','sort','assist','learn'],['Pick and place','Object sorting','Bench assistance','Education / experimentation']],
 upperLength:['Upper arm pivot spacing (mm)',60,450,1],foreLength:['Forearm pivot spacing (mm)',60,450,1],toolLength:['Wrist-to-grasp distance (mm)',20,200,1],payload:['Maximum payload / grasped weight (kg)',.01,20,.01],joints:['Arm joints, excluding gripper',3,6,1],gripOpening:['Gripper opening (mm)',10,160,1],upperMass:['Upper arm assembly mass (kg)',.01,5,.01],foreMass:['Forearm assembly mass (kg)',.01,5,.01],toolMass:['Wrist + gripper mass (kg)',.01,5,.01],margin:['Static torque multiplier',1,4,.1],bodyLength:['Body length (mm)',80,600,1],bodyWidth:['Body width (mm)',60,400,1],wheelDiameter:['Wheel / drive roller diameter (mm)',30,220,1],trackWidth:['Track width (mm)',15,100,1],robotMass:['Robot mass, excluding payload (kg)',.1,30,.1],speed:['Target speed (m/s)',.05,3,.05],slope:['Maximum incline (degrees)',0,35,1],terrain:['Terrain',['indoor','outdoor','rough'],['Indoor / smooth','Outdoor / paved','Uneven / rough']],legs:['Number of legs',['4','6'],['4 · quadruped','6 · hexapod']],legJoints:['Joints per leg',2,3,1],legLength:['Leg segment length (mm)',40,250,1],travelX:['X travel (mm)',50,1000,1],travelY:['Y travel (mm)',50,1000,1],travelZ:['Z travel (mm)',20,500,1],carriageWidth:['Carriage width (mm)',40,200,1],precision:['Target positioning tolerance (mm)',.05,5,.05],feedRate:['Target travel speed (mm/s)',1,200,1],panRange:['Pan travel (degrees)',30,270,1],tiltRange:['Tilt travel (degrees)',20,180,1],toolOffset:['Payload offset from tilt axis (mm)',10,200,1],mountWidth:['Mount width (mm)',40,200,1]
};
const partNames={plate:'Chassis plate',wheel:'Wheel with axle bore',bracket:'L mounting bracket',upper:'Upper arm link',forearm:'Forearm link',jaw:'Gripper finger',base:'Mounting base',enclosure:'Open electronics tray',sensor:'Sensor mounting plate',roller:'Track roller',leg:'Leg segment',foot:'Foot pad',carriage:'Gantry carriage'};
const partRanges={length:[30,600],width:[20,400],thickness:[3,40],hole:[3,16],current:[100,10000],runtime:[.1,24]};
function purposeMarkup(){
 document.querySelector('nav').insertAdjacentHTML('afterbegin','<button data-tab="purpose">◇ <span>Robot purpose</span></button>');
 document.querySelector('.steps').innerHTML='<button data-tab="purpose"><i>01</i> Define purpose</button><button data-tab="design"><i>02</i> Design parts</button><button data-tab="electronics"><i>03</i> Electronics</button><button data-tab="code"><i>04</i> Generate code</button>';
 document.querySelector('.project-type').innerHTML='<span id="familyBadge"></span> <span>• Draft</span>';
 const section=document.createElement('section');section.id='purpose';section.className='page';section.innerHTML=`<div class="purpose-intro"><div class="eyebrow">START WITH WHAT IT SHOULD DO</div><h2>What kind of robot are you building?</h2><p>Choose a platform, define its job, then shape the parts around it.</p></div><div class="family-grid">${Object.entries(families).map(([id,f])=>`<button class="family-card" data-family="${id}" aria-pressed="false"><span class="family-icon">${f.icon}</span><b>${f.name}</b><small>${f.tag}</small><p>${f.description}</p><span class="chosen">✓ Selected</span></button>`).join('')}</div><div class="purpose-layout"><article class="card"><div class="panel-title"><span id="configTitle">Requirements</span><span class="pill">Saved with project</span></div><div id="purposeFields" class="purpose-fields"></div></article><article class="card purpose-summary"><div class="eyebrow">YOUR DESIGN BRIEF</div><h2 id="briefTitle"></h2><div id="briefDiagram"></div><div id="briefMetrics"></div><p class="hint" id="briefNotes"></p><button class="primary full" id="toParts">Continue to parts →</button><p class="hint">Part presets use these requirements. Apply a preset in the design studio to update its geometry.</p></article></div>`;
 $('design').before(section);
 for(const [id,spec] of Object.entries(fieldSpecs)){const wrap=document.createElement('div');wrap.dataset.field=id;const label=document.createElement('label');label.htmlFor=id;label.textContent=spec[0];let input=document.createElement(Array.isArray(spec[1])?'select':'input');input.id=id;if(Array.isArray(spec[1]))spec[1].forEach((v,i)=>{const o=document.createElement('option');o.value=v;o.textContent=spec[2][i];input.append(o)});else{input.type='number';[input.min,input.max,input.step]=spec.slice(1)}wrap.append(label,input);$('purposeFields').append(wrap);}
 const mission=$('mission');const missionWrap=document.createElement('div');missionWrap.dataset.field='mission';const ml=document.createElement('label');ml.htmlFor='mission';ml.textContent='Control purpose';mission.previousElementSibling.remove();missionWrap.append(ml,mission);$('purposeFields').append(missionWrap);
 document.querySelector('#electronics h2').textContent='Select the controller';
 document.querySelector('#electronics .card p').textContent='Your robot purpose determines the actuator and sensor requirements below.';
 $('part').insertAdjacentHTML('beforebegin','<div class="part-context"><b id="partsFamily"></b><p id="presetInfo"></p><button id="applyPreset">↺ Apply purpose dimensions</button></div>');
 const input=document.createElement('input');input.id='family';input.type='hidden';$('purposeFields').append(input);
 for(const [id,[min,max]] of Object.entries(partRanges)){const el=$(id);el.min=min;el.max=max;}
 document.querySelector('#electronics .card:last-child > p').id='wiringIntro';
 document.querySelector('#code .note').id='codeNote';
 document.querySelector('#guide .guide').insertAdjacentHTML('afterbegin','<li><b>Start with your robot’s purpose</b><p id="purposeGuide"></p></li>');
}
function armLoads(s){const a=s.upperLength/1000,b=s.foreLength/1000,c=s.toolLength/1000;return {reach:s.upperLength+s.foreLength+s.toolLength,shoulder:9.81*s.margin*(s.payload*(a+b+c)+s.toolMass*(a+b+c/2)+s.foreMass*(a+b/2)+s.upperMass*a/2),elbow:9.81*s.margin*(s.payload*(b+c)+s.toolMass*(b+c/2)+s.foreMass*b/2)};}
function preset(s,part){let p={length:s.bodyLength,width:s.bodyWidth,thickness:5,hole:4};switch(part){case 'upper':case 'forearm':p={length:s[part==='upper'?'upperLength':'foreLength']+24,width:36,thickness:8,hole:6};break;case 'leg':p={length:s.legLength+24,width:28,thickness:7,hole:5};break;case 'jaw':p={length:Math.max(30,s.toolLength),width:Math.max(20,s.gripOpening/2+12),thickness:8,hole:4};break;case 'wheel':case 'roller':p={length:s.wheelDiameter,width:40,thickness:part==='roller'?s.trackWidth:18,hole:6};break;case 'base':p={length:s.family==='arm'?Math.min(300,Math.max(80,(s.upperLength+s.foreLength)*.4)):s.family==='turret'?s.mountWidth:120,width:s.family==='turret'?s.mountWidth:100,thickness:8,hole:5};break;case 'bracket':p={length:70,width:50,thickness:6,hole:4};break;case 'sensor':p={length:s.family==='turret'?s.mountWidth:60,width:40,thickness:4,hole:3};break;case 'enclosure':p={length:100,width:70,thickness:25,hole:4};break;case 'foot':p={length:45,width:30,thickness:8,hole:4};break;case 'carriage':p={length:s.carriageWidth,width:s.carriageWidth,thickness:8,hole:5};break;}for(const k in p)p[k]=Math.round(Math.max(partRanges[k][0],Math.min(partRanges[k][1],p[k])));return p;}
function applyPreset(){Object.assign(state,preset(state,state.part));state=valid(state);sync();save();toast('Purpose dimensions applied to '+partNames[state.part]);}
function purposeSummary(){const f=families[state.family];$('familyBadge').textContent=f.name.toUpperCase();$('configTitle').textContent=f.name+' requirements';$('briefTitle').textContent=f.name;$('partsFamily').textContent=f.name+' · component library';$('presetInfo').textContent='Suggested: '+Object.entries(preset(state,state.part)).filter(([k])=>k!=='hole').map(([,v])=>v).join(' × ')+' mm. Dimensions can be edited below.';
 document.querySelectorAll('[data-field]').forEach(e=>e.hidden=!f.fields.includes(e.dataset.field));document.querySelectorAll('[data-family]').forEach(e=>{const chosen=e.dataset.family===state.family;e.classList.toggle('selected',chosen);e.setAttribute('aria-pressed',String(chosen))});
 let metrics=[],notes='',diagram='';
 if(state.family==='arm'){const q=armLoads(state);metrics=[['Maximum straight reach',q.reach+' mm'],['Expected grasped weight',state.payload+' kg'],['Actuator channels',(state.joints+1)+' · joints + gripper'],['Shoulder torque estimate',q.shoulder.toFixed(2)+' N·m'],['Elbow torque estimate',q.elbow.toFixed(2)+' N·m']];notes='Worst-case horizontal static load × '+state.margin+'. Includes uniform link masses and tool mass at its midpoint; excludes acceleration, friction, and off-axis loads. This is a sizing estimate, not a verified payload rating. Check continuous actuator torque, bearings, print strength, and base stability.';const a=state.upperLength/q.reach*250,b=state.foreLength/q.reach*250,c=state.toolLength/q.reach*250;diagram=`<svg viewBox="0 0 340 160" role="img" aria-label="Arm reach schematic, not assembly geometry"><path d="M30 130 H70 M50 130 V90" stroke="#6a795b" stroke-width="10"/><path d="M50 90 h${a}" stroke="#e76a42" stroke-width="12"/><path d="M${50+a} 90 h${b}" stroke="#87956e" stroke-width="10"/><path d="M${50+a+b} 90 h${c} m0 -12 v24" stroke="#566449" stroke-width="5"/>${[50,50+a,50+a+b].map(x=>`<circle cx="${x}" cy="90" r="8" fill="#f8f8f1" stroke="#566449" stroke-width="3"/>`).join('')}<text x="50" y="42">${state.upperLength} + ${state.foreLength} + ${state.toolLength} mm</text><text x="50" y="152">STRAIGHT REACH · ${q.reach} mm</text></svg>`;}
 else if(['rover','tracked'].includes(state.family)){const rpm=state.speed/(Math.PI*state.wheelDiameter/1000)*60;const torque=(state.robotMass+state.payload)*9.81*Math.sin(state.slope*Math.PI/180)*state.wheelDiameter/2000/2;metrics=[['Platform footprint',state.bodyLength+' × '+state.bodyWidth+' mm'],['Total estimated mass',(state.robotMass+state.payload).toFixed(2)+' kg'],['Drive output speed',rpm.toFixed(0)+' RPM'],['Incline torque / side',torque.toFixed(2)+' N·m'],['Terrain',fieldSpecs.terrain[2][fieldSpecs.terrain[1].indexOf(state.terrain)]]];notes='Two driven sides. RPM assumes no slip; incline torque only includes gravity, excluding rolling resistance, skid steering, acceleration, and losses. Tracked robots require a matched track and sprocket system; the printable roller is an idler blank.';}
 else if(state.family==='walker'){metrics=[['Configuration',state.legs+' legs × '+state.legJoints+' joints'],['Servo channels',state.legs*state.legJoints],['Link length',state.legLength+' mm'],['Total estimated mass',(state.robotMass+state.payload).toFixed(2)+' kg']];notes='Plan joint bearings, foot contact, balance sensing, and a multi-channel servo controller. Leg segments are printable blanks; gait, inverse kinematics, and stability require a separate implementation.';}
 else if(state.family==='gantry'){metrics=[['Working envelope',state.travelX+' × '+state.travelY+' × '+state.travelZ+' mm'],['Payload',state.payload+' kg'],['Target tolerance','± '+state.precision+' mm'],['Target speed',state.feedRate+' mm/s']];notes='Travel and tolerance are requirements, not guaranteed results. Select rails, screws or belts, gearing, motors, endstops, and a Z brake/counterbalance for the load. Printed parts supplement purchased linear hardware.';}
 else {metrics=[['Pan / tilt travel',state.panRange+'° / '+state.tiltRange+'°'],['Payload',state.payload+' kg'],['Tilt static load',(state.payload*9.81*state.toolOffset/1000).toFixed(2)+' N·m'],['Actuator channels','2']];notes='Tilt load includes payload only. Add mount weight and a sizing margin. Select actuators with the required mechanical travel; the firmware pulse range must be calibrated to the actual servos.';}
 $('briefDiagram').innerHTML=diagram;$('briefMetrics').innerHTML=metrics.map(([label,value])=>`<div class="brief-row"><span>${label}</span><b>${value}</b></div>`).join('');$('briefNotes').textContent=notes;$('purposeGuide').textContent=f.description+' '+notes;
}
function initPurpose(){document.querySelectorAll('[data-family]').forEach(e=>e.onclick=()=>{state.family=e.dataset.family;state.part=families[state.family].parts[0];Object.assign(state,preset(state,state.part));sync();save()});$('applyPreset').onclick=applyPreset;$('toParts').onclick=()=>tab('design');$('part').addEventListener('change',applyPreset);sync();tab('purpose');}

function purposeRows(){const s=state,b=boards[s.board],common=[[b.name,'1','Controller · '+b.logic+' logic'],['Regulated actuator supply + fuse','1','Size for simultaneous peak actuator current; common ground'],['Mechanical disconnect / power switch','1','Accessible shutdown; support gravity-loaded axes']];if(['rover','tracked'].includes(s.family)){const r=roverRows();if(s.family==='tracked')r.push(['Matched tracks and drive sprockets','2 sets','Select a compatible pitch and tension system']);r.push(['Motor speed requirement','2', (s.speed/(Math.PI*s.wheelDiameter/1000)*60).toFixed(0)+' output RPM before slip']);return r;}
 if(s.family==='arm'){const q=armLoads(s);return [...common,['Positional joint actuators',String(s.joints),'Shoulder ≥ '+q.shoulder.toFixed(2)+' N·m; elbow ≥ '+q.elbow.toFixed(2)+' N·m static estimate with multiplier'],['Gripper actuator','1','Opening '+s.gripOpening+' mm; force depends on friction and linkage'],['Joint bearings, shafts, fasteners',String(s.joints),'Match bores and actual actuator interfaces'],['Base / bench attachment','1','Resist overturning at '+q.reach+' mm reach'],['Position or limit feedback','As needed','Recommended for calibration and travel limits']];}
 if(s.family==='turret')return [...common,['Positional servos','2','Pan '+s.panRange+'°, tilt '+s.tiltRange+'°; verify actual servo travel'],['Camera / sensor','1','Payload '+s.payload+' kg; interface selected separately'],['Bearing / supported pivot','2','Avoid carrying all side load through servo shaft']];
 if(s.family==='walker')return [...common,['Joint servos',String(s.legs*s.legJoints),'Size against stance geometry and robot load'],['Servo controller channels',String(s.legs*s.legJoints),'Dedicated controller required; device-specific driver not generated'],['IMU + foot contact sensors','1 + '+s.legs,'Balance and stance feedback'],['Joint bearings / compliant feet',String(s.legs),'Check ground clearance and support polygon']];
 return [...common,['Stepper / servo axes and matching drivers','3','Choose torque and current for payload, acceleration and transmission'],['Linear rails + transmission','3 axes',s.travelX+' / '+s.travelY+' / '+s.travelZ+' mm travel, plus carriage length'],['Homing switches','3 minimum','Normally-closed wiring with fault handling'],['Z-axis holding brake / counterbalance','1','Prevent payload drop on power loss']];
}
function servoPins(){return ({uno:[2,3,4,5,6,7,8],esp32:[18,19,21,22,25,26,27],pico:[2,3,4,6,7,8,9]})[state.board].slice(0,state.family==='arm'?state.joints+1:2);}
function servoNames(){return state.family==='arm'?Array.from({length:state.joints},(_,i)=>['Base rotation','Shoulder','Elbow','Wrist pitch','Wrist roll','Tool rotation'][i]).concat('Gripper'):['Pan','Tilt'];}
function purposeFirmware(){if(['rover','tracked'].includes(state.family))return roverFirmware();if(['walker','gantry'].includes(state.family)){const values=state.family==='walker'?{legs:state.legs,joints_per_leg:state.legJoints,segment_mm:state.legLength,payload_kg:state.payload}:{travel_x_mm:state.travelX,travel_y_mm:state.travelY,travel_z_mm:state.travelZ,payload_kg:state.payload,tolerance_mm:state.precision,speed_mm_s:state.feedRate};if(state.board==='uno')return '// Robot Factory | '+families[state.family].name+' | configuration scaffold only\n// Select and integrate the actual actuator drivers before adding motion.\n'+Object.entries(values).map(([k,v])=>'const float '+k.toUpperCase()+' = '+v+';').join('\n')+'\nvoid setup() { Serial.begin(115200); Serial.println("Configuration only - motion disabled"); }\nvoid loop() {}\n';return '# Robot Factory | '+families[state.family].name+' | configuration scaffold only\n# Select and integrate actuator drivers, limits, and motion planning.\n'+Object.entries(values).map(([k,v])=>k.toUpperCase()+' = '+v).join('\n')+'\nprint("Configuration only - motion disabled")\n';}
 const pins=servoPins(),names=servoNames(),comment=state.family==='arm'?'Reach '+armLoads(state).reach+' mm; payload '+state.payload+' kg. No inverse kinematics.':'Pan '+state.panRange+' deg; tilt '+state.tiltRange+' deg. Pulse limits need calibration.';
 if(state.board==='uno')return `// Robot Factory | ${families[state.family].name} | Arduino Uno R3\n// Install the Arduino Servo library. Positional PWM servos only.\n// ${comment}\n// No signal at boot. Send channel,pulse_us + newline (e.g. 0,1500).\n// Calibrate unloaded; pulse bounds do NOT guarantee mechanical limits.\n// X detaches all: support the arm first because it can fall.\n// Last commanded position is held; no automatic gravity-axis release.\n#include <Servo.h>\n#include <stdio.h>\nconst int COUNT=${pins.length};\nconst int PINS[COUNT]={${pins.join(',')}};\n// Channels: ${names.map((n,i)=>i+' '+n).join('; ')}\nServo axes[COUNT];\nchar buffer[32];\nunsigned int used=0;\nbool overflow=false;\nvoid setup() { Serial.begin(115200); }\nvoid loop() {\n  while(Serial.available()) {\n    char c=Serial.read();\n    if(c=='X') {\n      for(int i=0;i<COUNT;i++) axes[i].detach();\n      used=0; overflow=false;\n    } else if(c=='\\n') {\n      buffer[used]='\\0';\n      int channel,pulse; char extra;\n      if(!overflow && sscanf(buffer,"%d,%d %c",&channel,&pulse,&extra)==2 &&\n         channel>=0 && channel<COUNT && pulse>=1000 && pulse<=2000) {\n        axes[channel].writeMicroseconds(pulse);\n        if(!axes[channel].attached()) axes[channel].attach(PINS[channel],1000,2000);\n        axes[channel].writeMicroseconds(pulse);\n      }\n      used=0; overflow=false;\n    } else if(c!='\\r') {\n      if(used<sizeof(buffer)-1) buffer[used++]=c;\n      else overflow=true;\n    }\n  }\n}\n`;
 return `# Robot Factory | ${families[state.family].name} | ${boards[state.board].name}\n# MicroPython, positional 50 Hz PWM servos only.\n# ${comment}\n# Channel mapping: ${names.map((n,i)=>i+' '+n).join('; ')}\n# Send channel,pulse_us + Enter. Example: 0,1500\n# 1000..2000 us is an initial bound, NOT calibrated mechanical travel.\n# No PWM at startup. X releases all axes: support the mechanism first.\n# Last command is held; no automatic gravity-axis release.\nfrom machine import Pin, PWM\nPINS = [${pins.join(', ')}]\naxes = {}\nfor pin in PINS:\n    Pin(pin, Pin.OUT, value=0)\ntry:\n    while True:\n        text = input().strip()\n        if text == 'X':\n            for pwm in axes.values():\n                pwm.deinit()\n            axes.clear()\n            for pin in PINS:\n                Pin(pin, Pin.OUT, value=0)\n            continue\n        try:\n            channel, pulse = map(int, text.split(','))\n            if not (0 <= channel < len(PINS) and 1000 <= pulse <= 2000):\n                raise ValueError()\n            if channel not in axes:\n                axes[channel] = PWM(Pin(PINS[channel]), freq=50, duty_u16=0)\n            axes[channel].duty_u16(round(pulse / 20000 * 65535))\n        except ValueError:\n            print('Use channel,pulse_us with pulse 1000..2000')\nfinally:\n    for pwm in axes.values():\n        pwm.deinit()\n    for pin in PINS:\n        Pin(pin, Pin.OUT, value=0)\n`;
}
function purposeHardwareUI(){const mobile=['rover','tracked'].includes(state.family),servo=['arm','turret'].includes(state.family);$('wiringIntro').textContent=mobile?'Two driven sides with two direction inputs and one PWM input per motor. Common ground; separate motor supply.':servo?'Positional servo signal wiring. Use a separate regulated servo supply rated for simultaneous peak current, and connect grounds.':'Planning scaffold: choose actual drivers before assigning control pins. No motor-motion firmware is generated for this platform.';
 if(servo)$('wiring').innerHTML='<table><thead><tr><th>Channel / joint</th><th>Signal pin</th><th>Connection</th></tr></thead><tbody>'+servoPins().map((p,i)=>`<tr><td>${i} · ${servoNames()[i]}</td><td>${state.board==='uno'?'D':'GPIO '}${p}</td><td>Servo signal · logic compatible</td></tr>`).join('')+'</tbody></table>';
 if(!mobile&&!servo)$('wiring').innerHTML='<p class="note">'+(state.family==='walker'?state.legs*state.legJoints+' actuator channels: select a multi-channel servo controller and its communication interface.':'Select three axis drivers, step/direction or bus interfaces, homing switches, and a hardware enable circuit.')+'</p>';
 $('codeNote').textContent=mobile?'Bench-test starter: motors stay stopped at startup; repeat commands within 500 ms. Lift the wheels for testing. Sensor calibration and autonomous behavior need integration.':servo?'Servo bench-control starter: outputs remain inactive until a serial command. Calibrate each joint unloaded and support gravity-loaded parts. Commands hold position; X releases servos and may let the mechanism fall. No trajectory planning or inverse kinematics.':'Configuration scaffold only. Your purpose dimensions are included, but actuator drivers, homing, coordinated motion, and gait control are not implemented.';
 $('codeDescription').textContent=boards[state.board].name+' · '+families[state.family].name+' · '+(mobile?'dual-motor control':servo?'individual servo control':'configuration scaffold');
 document.querySelector('#guide .guide li:last-child p').textContent=mobile?'Test wheels raised. The starter stops after 500 ms without a valid command. Integrate and calibrate sensors before floor tests.':'Validate joint direction, limits, load capacity, and power-off behavior before loading the mechanism. Generated geometry is a component starting point; hardware interfaces and structural capacity need validation.';
}
// A rectangular cell extrusion gives closed shells, including through-holes and trays.
function extrudeCells(xs,ys,heights){for(let i=0;i<xs.length-1;i++)for(let j=0;j<ys.length-1;j++){const z=heights(i,j);if(!z)continue;const x=xs[i],X=xs[i+1],y=ys[j],Y=ys[j+1];quad([x,y,0],[x,Y,0],[X,Y,0],[X,y,0]);quad([x,y,z],[X,y,z],[X,Y,z],[x,Y,z]);const edge=(ni,nj,pts)=>{const n=heights(ni,nj);if(z>n){const levels=[n,...[3].filter(v=>v>n&&v<z),z];for(let k=0;k<levels.length-1;k++)quad(...pts(levels[k],levels[k+1]));}};edge(i,j-1,(a,b)=>[[x,y,a],[X,y,a],[X,y,b],[x,y,b]]);edge(i+1,j,(a,b)=>[[X,y,a],[X,Y,a],[X,Y,b],[X,y,b]]);edge(i,j+1,(a,b)=>[[X,Y,a],[x,Y,a],[x,Y,b],[X,Y,b]]);edge(i-1,j,(a,b)=>[[x,Y,a],[x,y,a],[x,y,b],[x,Y,b]]);}}
function purposeMesh(){const L=state.length,W=state.width,T=state.thickness,H=state.hole;mesh=[];if(['upper','forearm','leg'].includes(state.part)){const inset=Math.min(12,L/4);const xs=[-L/2,-L/2+inset-H/2,-L/2+inset+H/2,L/2-inset-H/2,L/2-inset+H/2,L/2],ys=[-W/2,-H/2,H/2,W/2];extrudeCells(xs,ys,(i,j)=>i<0||i>=5||j<0||j>=3||([1,3].includes(i)&&j===1)?0:T);return;}
 if(state.part==='enclosure'){const wall=3;extrudeCells([-L/2,-L/2+wall,L/2-wall,L/2],[-W/2,-W/2+wall,W/2-wall,W/2],(i,j)=>i<0||j<0||i>2||j>2?0:(i===1&&j===1?3:Math.max(6,T)));return;}
 if(['jaw','foot'].includes(state.part)){const xs=[-L/2,L/2-8,L/2],ys=[-W/2,-W/2+8,W/2];extrudeCells(xs,ys,(i,j)=>i<0||j<0||i>1||j>1?0:(state.part==='foot'||i===1||j===0?T:0));return;}
 const original=state.part;state.part=['roller'].includes(original)?'wheel':['base','sensor','carriage'].includes(original)?'plate':original;originalMesh();state.part=original;
}
function purposePartUI(){const p=state.part,ring=['wheel','roller'].includes(p),link=['upper','forearm','leg'].includes(p),noHole=['jaw','foot','bracket','enclosure'].includes(p);$('lLabel').textContent=ring?'Outer diameter':link?'Link length':'Length';$('wLabel').textContent=p==='bracket'?'Upright height':'Width';$('width').closest('.field').style.display=ring?'none':'';$('hole').closest('.field').style.display=noHole?'none':'';$('hLabel').textContent=ring?'Axle bore diameter':'Through-hole size (square)';$('partTitle').textContent=partNames[p];const notes={upper:'Two square pivot holes, 12 mm from ends (or one quarter of the length on short links). Check fit to actual shafts and servo horns.',forearm:'Two square pivot holes. Length is end-to-end; pivot spacing is shorter by twice the end inset.',leg:'Two square pivot holes. Link blank only; actuator interfaces require fitting.',jaw:'One L-shaped finger blank. Print a mirrored pair and design the linkage to achieve your desired opening.',enclosure:'Open tray with 3 mm walls and floor. Thickness sets outer height (minimum 6 mm). Add cable openings as needed.',roller:'Smooth idler roller with axle bore; not a toothed drive sprocket.',foot:'Solid rectangular foot pad. Add a compliant contact layer.',base:'Four square through-holes. Verify bolt fit and stability against overturning.',sensor:'Four square through-holes. Match your sensor’s mounting pattern.',carriage:'Four square through-holes. Adapt to the chosen linear bearings.'};if(notes[p])$('partHint').textContent=notes[p];const points=mesh.flat();const dims=[0,1,2].map(i=>Math.max(...points.map(p=>p[i]))-Math.min(...points.map(p=>p[i])));$('bounds').textContent=dims.map(v=>+v.toFixed(1)).join(' × ');}

